// Replays bot-vs-bot matches exported from the Unity C# rules (tests/fixtures/unity_traces.json,
// generated by the Unity logic runner) and checks every round result is identical in the TypeScript port.
import { describe, expect, it } from 'vitest';
import fixture from './fixtures/unity_traces.json';
import { buildContent } from '../src/data';
import { botChoose, MatchAuthority, MatchPhase, PlayerSlot } from '../src/core';
import { DeterministicRandom } from '../src/core/random';
import { v6Baseline } from '../src/core/types';

const traces: any[] = fixture as any;

describe('Unity v6 parity (full match traces)', () => {
  it(`replays ${traces.length} Unity matches round-by-round`, () => {
    const content = buildContent();
    let rounds = 0;
    for (const g of traces) {
      const opts = { ...v6Baseline(), ...g.options };
      const a = new MatchAuthority(content, opts);
      a.startNewMatch(g.seed);
      const rng = new DeterministicRandom(g.seed ^ 0x5f3759df);
      for (const tr of g.rounds) {
        const ctx = `seed ${g.seed} round ${tr.round}`;
        const cmds: any[] = [];
        const mps: number[] = [];
        const hands: string[] = [];
        for (const s of [PlayerSlot.P1, PlayerSlot.P2]) {
          const view = a.getPrivateView(s);
          mps.push(view.mp);
          hands.push(view.hand.map(c => c.uid).join('|'));
          const st = a.getPublicState();
          const c = botChoose(content, view, st.field, st.options, rng);
          c.slot = s;
          const res = a.submit(c);
          cmds.push({ uid: c.cardUid, pass: c.pass, extra: c.extraMp, ok: res.ok });
        }
        expect(mps, ctx).toEqual(tr.mp);
        expect(hands, ctx).toEqual(tr.hands);
        expect(cmds, ctx).toEqual(tr.cmds);
        const lr = a.getPublicState().lastResult!;
        for (const [k, p] of [['p1', lr.p1], ['p2', lr.p2]] as const) {
          const t = tr[k];
          expect(p.cardId, ctx).toBe(t.card);
          expect({ atk: p.stats.atk, def: p.stats.def, pierce: p.stats.pierce, gain: p.stats.gain, mods: p.stats.mods.map(m => m.label) }, ctx).toEqual(t.stats);
          const af = p.afterHit;
          expect({ gain: af.gain, standing: af.standing, baseGain: af.baseGain, rawBaseGain: af.rawBaseGain, otherGain: af.otherGain, investGain: af.investGain, extraGain: af.extraGain, mpTax: af.mpTax, washout: af.washout, washoutTarget: af.washoutTarget }, ctx).toEqual(t.after);
          expect(p.mpSpent, ctx).toBe(t.mpSpent);
        }
        const o = lr.outcome;
        expect({ result: o.result, failedP1: o.failedP1, failedP2: o.failedP2, damageToP1: o.damageToP1, damageToP2: o.damageToP2, isSpecial: o.isSpecial, selfDamage: o.selfDamage }, ctx).toEqual(tr.outcome);
        expect(lr.gains.map(x => [x.element, x.amount, x.source]), ctx).toEqual(tr.gains);
        expect(lr.fieldAfter.values, ctx).toEqual(tr.fieldAfter);
        expect(lr.fieldNameAfter, ctx).toBe(tr.fieldName);
        expect(lr.hpAfter, ctx).toEqual(tr.hpAfter);
        expect(lr.mpTaxApplied, ctx).toEqual(tr.tax);
        expect(lr.outcomeAfter, ctx).toBe(tr.outcomeAfter);
        rounds++;
        if (a.getPublicState().phase === MatchPhase.GameOver) break;
        a.readyForNextRound(PlayerSlot.P1);
        a.readyForNextRound(PlayerSlot.P2);
      }
    }
    expect(rounds).toBeGreaterThan(1000);
  });
});
